);

CREATE TABLE `organization` (
  `continent` TEXT,
  `homepage` TEXT,
  `name` TEXT,
  `oid` NUMBER,
  PRIMARY KEY (`oid`)
);

CREATE TABLE `publication_keyword` (
  `pid` NUMBER REFERENCES `publication`(`pid`),
  `kid` NUMBER REFERENCES `keyword`(`kid`),
  PRIMARY KEY (`kid`)
);

CREATE TABLE `writes` (
  `aid` NUMBER REFERENCES `author`(`aid`),
  `pid` NUMBER REFERENCES `publication`(`pid`),
  PRIMARY KEY (`aid`)
);

CREATE TABLE `cite` (
  `cited` NUMBER REFERENCES `publication`(`pid`),
  `citing` NUMBER REFERENCES `publication`(`pid`)
);

