Database Schema:
CREATE TABLE `country` (
  `id` INTEGER,
  `country_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `ranking_system` (
  `id` INTEGER,
  `system_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `ranking_criteria` (
