Database Schema:
CREATE TABLE `Document_Types` (
  `document_type_code` TEXT,
  `document_description` TEXT,
  PRIMARY KEY (`document_type_code`)
);

CREATE TABLE `Documents` (
  `document_id` NUMBER,
  `document_type_code` TEXT REFERENCES `Document_Types`(`document_type_code`),
  `grant_id` NUMBER REFERENCES `Grants`(`grant_id`),
  `sent_date` TIME,
  `response_received_date` TIME,
  `other_details` TEXT,
  PRIMARY KEY (`document_id`)
);

CREATE TABLE `Grants` (
  `grant_id` NUMBER,
  `organisation_id` NUMBER REFERENCES `Organisations`(`organisation_id`),
  `grant_amount` NUMBER,
  `grant_start_date` TIME,
  `grant_end_date` TIME,
  `other_details` TEXT,
  PRIMARY KEY (`grant_id`)
);

CREATE TABLE `Organisation_Types` (
  `organisation_type` TEXT,
  `organisation_type_description` TEXT,
  PRIMARY KEY (`organisation_type`)
);

CREATE TABLE `Organisations` (
  `organisation_id` NUMBER,
  `organisation_type` TEXT REFERENCES `Organisation_Types`(`organisation_type`),
  `organisation_details` TEXT,
  PRIMARY KEY (`organisation_id`)
);

CREATE TABLE `Project_Outcomes` (
  `project_id` NUMBER REFERENCES `Projects`(`project_id`),
  `outcome_code` TEXT REFERENCES `Research_Outcomes`(`outcome_code`),
  `outcome_details` TEXT
);

CREATE TABLE `Project_Staff` (
  `staff_id` NUMBER,
  `project_id` NUMBER REFERENCES `Projects`(`project_id`),
  `role_code` TEXT REFERENCES `Staff_Roles`(`role_code`),
  `date_from` TIME,
  `date_to` TIME,
  `other_details` TEXT,
  PRIMARY KEY (`staff_id`)
);

CREATE TABLE `Projects` (
  `project_id` NUMBER,
  `organisation_id` NUMBER REFERENCES `Organisations`(`organisation_id`),
  `project_details` TEXT,
  PRIMARY KEY (`project_id`)
);

CREATE TABLE `Research_Outcomes` (
  `outcome_code` TEXT,
  `outcome_description` TEXT,
  PRIMARY KEY (`outcome_code`)
);

CREATE TABLE `Research_Staff` (
  `staff_id` NUMBER,
  `employer_organisation_id` NUMBER REFERENCES `Organisations`(`organisation_id`),
  `staff_details` TEXT,
  PRIMARY KEY (`staff_id`)
);

CREATE TABLE `Staff_Roles` (
  `role_code` TEXT,
  `role_description` TEXT,
  PRIMARY KEY (`role_code`)
);

CREATE TABLE `Tasks` (
  `task_id` NUMBER,
  `project_id` NUMBER REFERENCES `Projects`(`project_id`),
  `task_details` TEXT,
  `eg Agree Objectives` TEXT,
  PRIMARY KEY (`task_id`)
);

