Database Schema:
CREATE TABLE `Investors` (
  `investor_id` NUMBER,
  `Investor_details` TEXT,
  PRIMARY KEY (`investor_id`)
);

CREATE TABLE `Lots` (
  `lot_id` NUMBER,
  `investor_id` NUMBER REFERENCES `Investors`(`investor_id`),
  `lot_details` TEXT,
  PRIMARY KEY (`lot_id`)
);

CREATE TABLE `Ref_Transaction_Types` (
  `transaction_type_code` TEXT,
  `transaction_type_description` TEXT,
  PRIMARY KEY (`transaction_type_code`)
);

CREATE TABLE `Transactions` (
  `transaction_id` NUMBER,
  `investor_id` NUMBER REFERENCES `Investors`(`investor_id`),
  `transaction_type_code` TEXT REFERENCES `Ref_Transaction_Types`(`transaction_type_code`),
  `date_of_transaction` TIME,
  `amount_of_transaction` NUMBER,
  `share_count` TEXT,
  `other_details` TEXT,
  PRIMARY KEY (`transaction_id`)
);

CREATE TABLE `Sales` (
  `sales_transaction_id` NUMBER REFERENCES `Transactions`(`transaction_id`),
  `sales_details` TEXT,
  PRIMARY KEY (`sales_transaction_id`)
);

CREATE TABLE `Purchases` (
  `purchase_transaction_id` NUMBER REFERENCES `Transactions`(`transaction_id`),
  `purchase_details` TEXT
);

CREATE TABLE `Transactions_Lots` (
  `transaction_id` NUMBER REFERENCES `Transactions`(`transaction_id`),
  `lot_id` NUMBER REFERENCES `Lots`(`lot_id`)
);

